import argparse,hashlib,json,pathlib,time
CASE_ID='mab-late-constraint-a1b76b3745'; SOURCE_ID='bargaining:034'; EVENT='sealed_lot_scope_clarified'; THEME='task_scope_or_dependency_change'; AUTHORITY={'power_requirement': 'none', 'condition_evidence': 'sealed_lot_certificate', 'shelf_life_months': 24, 'unit_price': 17.5, 'minimum_batch': 60, 'delivery_days': 5}
